import {createPronunciation} from './pronunciation.js';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const grammarNotes={
 'Second conditional':'If + past simple, would + fe’l: hozirgi yoki kelajakdagi taxminiy holat. Masalan: If I had more time, I would read more.',
 'Present perfect continuous':'Have/has + been + V-ing: o‘tmishda boshlangan va hozirgacha davom etgan jarayon. Masalan: I have been studying for two years.',
 'Present perfect':'Have/has + V3: o‘tmishdagi ishning hozirgi natijasi yoki hayotiy tajriba. Masalan: I have learned a lot.',
 'Past perfect':'Had + V3: o‘tmishdagi boshqa voqeadan oldin tugagan ish. Masalan: I had finished before she arrived.',
 'Past perfect continuous':'Had + been + V-ing: o‘tmishdagi bir nuqtaga qadar davom etgan jarayon. Masalan: I had been waiting for an hour.',
 'Third conditional':'If + had + V3, would/could/might have + V3: o‘tmishda bo‘lmagan holat va uning taxminiy natijasi. Masalan: If I had practised, I would have improved.',
 'Inverted conditional':'Had + ega + V3: if ishlatmasdan shartni ifodalash. Masalan: Had I known, I would have helped.'};
export function annotatedText(block){const spans=block.annotations||[];let cursor=0,out='';for(const a of spans){const at=Number.isInteger(a.start)?a.start:block.text.indexOf(a.text,cursor);if(at<cursor||block.text.slice(at,at+a.text.length)!==a.text)continue;out+=e(block.text.slice(cursor,at))+'<mark class="guide-'+(a.type==='gr'?'grammar':'vocab')+'" title="'+(a.type==='gr'?'Grammatik tuzilma':'Foydali ibora')+'">'+e(a.text)+'</mark>';cursor=at+a.text.length;}return out+e(block.text.slice(cursor));}
let bank=null,loading=false,problem='',part='Part 1',index=0,query='',mode='both',scale=1,timed=false,remaining=120,timer=null;
const audio=createPronunciation({getPreferences:()=>({accent:'en-GB',rate:.9}),onError:m=>{const s=document.querySelector('#guide-status');if(s)s.textContent=m;}});
export function guideView(){if(!bank)return `<section class="panel"><h1>Speaking guide</h1><p role="status">${e(problem||'To‘liq qo‘llanma yuklanmoqda…')}</p></section>`;
 const topics=bank.topics.filter(t=>t.part===part),topic=topics[index]||topics[0];let question=false,answer=false;
 let body=topic.blocks.map((b,i)=>{if(/^Q\d+$/.test(b.text)){question=true;answer=false;return `<hr><span class="tag">${e(b.text)}</span>`;}if(question){question=false;return `<h3>${e(b.text)}</h3>`;}if(/^(OPTION [ABC]|ANSWER \d+|VERSION [ABC]|THE UNIVERSAL ANSWER|Prep plan)/i.test(b.text))answer=true;
 const cls=answer?'guide-answer':'';
 if(b.type==='paragraph')return `<div class="${cls} guide-paragraph"><p>${annotatedText(b)}</p>${b.text.length>120?`<button class="text-btn" data-guide-audio="${i}" aria-label="Shu paragrafni tinglash">Tinglash</button>`:''}</div>`;
 if(grammarNotes[b.text])return `<details class="guide-grammar-note ${cls}"><summary>${e(b.text)}</summary><p>${e(grammarNotes[b.text])}</p></details>`;
 if(b.text==='Grammar')return `<h4 class="${cls} guide-grammar">GRAMMAR</h4>`;
 return `<p class="${cls} ${b.type==='listitem'?'guide-bullet':'guide-label'}">${e(b.text)}</p>`;
 }).join('');
 let opened=false;body=body.replace(/<hr><span class="tag">(Q\d+)<\/span><h3>([\s\S]*?)<\/h3>/g,(_,n,q)=>{const close=opened?'</details>':'';const first=!opened;opened=true;return close+'<details class="guide-question" '+(first?'open':'')+'><summary><span>'+n+'</span> '+q+'</summary>';});if(opened)body+='</details>';
 return `<section class="speaking-guide"><div class="page-heading"><div><span class="eyebrow">TO‘LIQ SPEAKING QO‘LLANMASI</span><h1>Speaking studio</h1><p>212 mavzu · Part 1, Part 2, P2 Masters va Part 3</p></div></div><div class="panel guide-toolbar"><label>Part<select id="guide-part">${['Part 1','Part 2','P2 Masters','Part 3'].map(p=>`<option ${p===part?'selected':''}>${p}</option>`).join('')}</select></label><label>Mavzu qidirish<input type="search" id="guide-search" value="${e(query)}" placeholder="Mavzu yoki savol"></label><label>Mavzu<select id="guide-topic">${topics.map((t,i)=>`<option value="${i}" ${i===index?'selected':''}>${i+1}. ${e(t.title)}</option>`).join('')}</select></label><label>Ko‘rinish<select id="guide-mode"><option value="both" ${mode==='both'?'selected':''}>Savollar + javoblar</option><option value="question" ${mode==='question'?'selected':''}>Faqat savollar</option></select></label><label>Matn o‘lchami<select id="guide-scale">${[1,1.2,1.4,1.6].map(n=>`<option value="${n}" ${scale===n?'selected':''}>${Math.round(n*100)}%</option>`).join('')}</select></label></div><p id="guide-status" role="status"></p><div class="guide-actions"><button class="btn" id="guide-prev" ${index===0?'disabled':''}>Oldingi mavzu</button><span>${index+1} / ${topics.length}</span><button class="btn" id="guide-next" ${index===topics.length-1?'disabled':''}>Keyingi mavzu</button><button class="btn" id="guide-focus">To‘liq ekran</button><button class="btn" id="guide-timer">${timed?'Taymerni to‘xtatish':'Vaqt bilan mashq'}</button><output id="guide-clock" aria-live="off">${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}</output></div><article class="panel guide-paper ${mode==='question'?'questions-only':''}" id="guide-paper" style="font-size:${scale}rem"><span class="eyebrow">${e(part)}</span><h2>${e(topic.title)}</h2><p class="help-text">Lexora Speaking · Namuna javoblarni o‘z tajribangizga moslang.</p><p class="guide-legend"><span class="guide-grammar">Grammatik tuzilma</span> <span class="guide-vocab">Foydali ibora</span></p><p class="help-text">Ko‘k belgi — grammatik tuzilma, yashil belgi — foydali ibora. Grammar nomini bosing va izohini oching.</p>${body}</article></section>`;
}
export function mountGuide(redraw){if(!bank){if(!loading&&!problem){loading=true;fetch('speaking-guide.json').then(r=>{if(!r.ok)throw Error('Qo‘llanma yuklanmadi.');return r.json();}).then(d=>{bank=d;redraw();}).catch(er=>{problem=er.message;redraw();}).finally(()=>loading=false);}return;}
 const $=s=>document.querySelector(s),topics=bank.topics.filter(t=>t.part===part),topic=topics[index];if(!$('#guide-part'))return;
 const draw=()=>{audio.stop();redraw();};$('#guide-part').onchange=ev=>{part=ev.target.value;index=0;query='';draw();};$('#guide-topic').onchange=ev=>{index=Number(ev.target.value);draw();};$('#guide-prev').onclick=()=>{index--;draw();};$('#guide-next').onclick=()=>{index++;draw();};$('#guide-mode').onchange=ev=>{mode=ev.target.value;draw();};$('#guide-scale').onchange=ev=>{scale=Number(ev.target.value);draw();};
 $('#guide-search').oninput=ev=>{query=ev.target.value;let count=0;for(const o of $('#guide-topic').options){const t=topics[Number(o.value)],match=(t.title+' '+t.blocks.map(b=>b.text).join(' ')).toLowerCase().includes(query.toLowerCase());o.hidden=!match;if(match)count++;}$('#guide-status').textContent=count+' ta mos mavzu. Mavzu ro‘yxatidan tanlang.';};
 document.querySelectorAll('[data-guide-audio]').forEach(b=>b.onclick=()=>audio.speak(topic.blocks[Number(b.dataset.guideAudio)].text));
 $('#guide-focus').onclick=()=>{const paper=$('#guide-paper');if(document.fullscreenElement)document.exitFullscreen?.();else paper.requestFullscreen?.().catch(()=>{$('#guide-status').textContent='Bu oynada to‘liq ekran qo‘llanmaydi.';});};
 $('#guide-timer').onclick=()=>{clearInterval(timer);timed=!timed;if(timed){remaining=part==='Part 1'?60:part==='Part 2'?180:120;timer=setInterval(()=>{remaining--;if($('#guide-clock'))$('#guide-clock').textContent=Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0');if(remaining<=0){clearInterval(timer);timed=false;if($('#guide-status'))$('#guide-status').textContent='Mashq vaqti tugadi.';}},1000);}draw();};
}
export function leaveGuide(){audio.stop();clearInterval(timer);timed=false;}
